{
  "qid": "0018-L2-01",
  "sample_id": "0018",
  "gen_prompt": "电影级写实宽银幕画面：暴雨夜的香港港区废弃船坞中，危险流浪者迎着风浪迈步前进，重心压低，作为画面唯一主角。采用低机位，相机位于主体正前方并稍偏向主体右侧；主体从顶端到落脚处完整入画，正面无遮挡，占画面中央约三分之二高度。两架黄色救援直升机并排悬停在左上方远景，冷白探照灯斜穿雨幕照向船坞；右后方防波堤外掀起一道巨浪，前景散落三只红色集装箱。凝固高速雨滴与海水飞沫，保持主体细节锐利，强烈纵深，16:9构图，不出现字幕、水印或边框。",
  "invocation": "L2",
  "knowledge_dim": "虚构载具的标志性构型、装甲配色、核心部件与尺度比例",
  "fidelity_checks": [
    {
      "check": "危险流浪者呈双足直立的人形Jaeger整体构型，各主要身体区段完整可辨，未变成轮式、履带式、四足或多足载具。",
      "lens": "K1",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "1",
          "8"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "主体缺少主要身体区段、上下结构无法辨认，或被画成坦克、汽车、履带平台、四足或多足机械等非人形类别。",
        "tier_1": "主体明确为完整的双足直立人形Jaeger，主要身体区段齐全且构型清楚，没有轮式、履带式或额外承重足结构。",
        "tier_2": "在满足Pass基础上，整体轮廓、承重框架和各主要身体区段的衔接均高度清晰，即使处于暴雨和迈步动作中仍能一眼辨认其完整人形Jaeger构型。"
      },
      "variants_used": "",
      "visibility_requirement": "题面要求主体全身正面无遮挡；若主体缺失、被裁切或雨雾遮蔽到无法核验整体构型，本条判为Fail，不作N/A。"
    },
    {
      "check": "主体外观由装甲板、机械关节及硬质机械组件拼合而成，不得在危险流浪者自身出现血肉、皮肤、鳞片、肌肉、毛发、触须或其他生物肢体。",
      "lens": "K1",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "1",
          "7"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "主体被画成有机怪兽，或主体明显带有血肉、皮肤、鳞片、肌肉、毛发、触须等生物组织；也包括装甲板和机械关节大面积缺失而呈软体生物结构。",
        "tier_1": "主体通体保持硬质装甲与机械关节拼装特征，没有可见有机组织或生物肢体。",
        "tier_2": "在满足Pass基础上，装甲分片、关节轴、液压或传动连接等机械层级丰富且逻辑清楚，所有暴露区域均保持可信的非生物构造。"
      },
      "variants_used": "",
      "visibility_requirement": "至少需清楚看到躯体和多个关节区域；题面已要求主体细节锐利，若主体表面模糊到无法区分机械构造与有机组织，本条判为Fail。"
    },
    {
      "check": "胸口正中具有清楚可辨的圆形涡轮状核能反应堆核心，圆形涡口居中并处于发光状态。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "4"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "胸口核心缺失、不发光、偏离正中，或被画成方形灯条、普通徽章、平面圆点等不具涡轮状结构的部件。",
        "tier_1": "胸口正中存在发光的圆形涡轮状核心，圆形轮廓、中央涡口和安装位置均清楚可辨。",
        "tier_2": "在满足Pass基础上，核心具有精密的同心环、叶片或内部层级，发光从结构内部透出且边界清晰，复杂度和辨识度显著高于普通圆灯。"
      },
      "variants_used": "",
      "visibility_requirement": "题面锁定正面无遮挡视角；若胸口被姿态、飞沫或其他物体遮住，或核心区域过小无法判断，本条判为Fail。"
    },
    {
      "check": "头部为封闭式装甲头盔或Conn-Pod造型，前脸表现为发光眼窗或面罩，不出现裸露的人类五官。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "5"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "头部缺失、敞开成裸露驾驶员面孔，或直接出现人类眼睛、鼻子、嘴等五官；也包括画成动物头颅或无装甲包覆的普通人头。",
        "tier_1": "头部具有完整封闭装甲外壳，前脸由发光眼窗或连续面罩构成，没有裸露人类五官。",
        "tier_2": "在满足Pass基础上，Conn-Pod外壳分片、前脸光窗、侧部连接与颈部安装关系均精细明确，封闭驾驶舱属性极强且无歧义。"
      },
      "variants_used": "",
      "visibility_requirement": "正面略偏侧视角必须能看清前脸；若该区域被裁掉、完全背向相机或细节糊成不可辨色块，本条判为Fail。"
    },
    {
      "check": "机体装甲的主导色相属于深蓝、钢蓝或蓝灰等蓝色系，而非其他色系。",
      "lens": "K2",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "主体装甲整体呈红、黄、绿、纯灰黑或其他非蓝色系，或蓝色仅为不显眼的小面积点缀。",
        "tier_1": "主体装甲的视觉主色明确属于深蓝、钢蓝或蓝灰色系，暴雨和环境光影响下仍可判断为蓝色主导。",
        "tier_2": "在满足Pass基础上，蓝色装甲在不同受光面、湿润表面与阴影中保持稳定色相，并呈现细腻而统一的深浅层次。"
      },
      "variants_used": "",
      "visibility_requirement": "需有足够面积的主体装甲处于可辨色状态；若全身因逆光或黑暗变成无色剪影而无法识别主色，本条判为Fail。"
    },
    {
      "check": "蓝色装甲占据机体最大表面积，银灰或其他辅色不得反客为主。",
      "lens": "K2",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "逐区观察可见蓝色覆盖面积不是最大，主体被银灰、黑色、红色或其他颜色大面积主导。",
        "tier_1": "蓝色覆盖主体躯干与肢体的主要装甲区域，按可见面积判断明确多于任一其他单一颜色。",
        "tier_2": "在满足Pass基础上，蓝色覆盖关系在全身各主要装甲区连续成立，辅色层级控制精准，即使受雨水高光影响也不存在主次误判。"
      },
      "variants_used": "",
      "visibility_requirement": "题面要求全身完整可见，须按全部可见装甲综合判断；若大面积被遮挡或曝光导致无法比较颜色覆盖面积，本条判为Fail。"
    },
    {
      "check": "机体上存在明确可辨的橙色或橙红色装饰板块或部件。",
      "lens": "K2",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "3"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "机体完全没有橙色或橙红色部件，或仅有环境反光、火花和灯光染色而没有实际装饰板块。",
        "tier_1": "机体装甲上至少有清晰、稳定且属于实体部件的橙色或橙红色装饰区域。",
        "tier_2": "在满足Pass基础上，橙色或橙红色部件具有清楚边界、装甲分缝与合理安装位置，多处呼应且不会被误认成环境光斑。"
      },
      "variants_used": "",
      "visibility_requirement": "至少一处橙色实体部件需清晰可见；若仅出现无法判断归属的彩色反光或细节过小，本条判为Fail。"
    },
    {
      "check": "橙色或橙红色仅作为辅色，与大面积蓝色主装甲形成清晰的蓝橙对比配色，不得颠倒主辅关系。",
      "lens": "K2",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "2",
          "3"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "没有形成蓝橙对比，橙色与蓝色之一缺失，或橙色覆盖过大成为主体主色，导致主辅关系颠倒。",
        "tier_1": "大面积蓝色装甲与较小面积橙色或橙红色部件同时清楚存在，蓝为主、橙为辅的对比关系明确。",
        "tier_2": "在满足Pass基础上，橙色部件被精准布置于关键结构节点，与蓝色装甲形成节奏清楚、全身协调且辨识度极高的对比体系。"
      },
      "variants_used": "",
      "visibility_requirement": "须同时看见足够面积的两类颜色以判断主辅关系；任何一类因遮挡、曝光或色偏而不可辨时，本条判为Fail。"
    },
    {
      "check": "头部自身呈紧凑的小型装甲头轮廓，不得膨大为巨型舱体、宽大动物头或接近上躯干宽度的块体。",
      "lens": "K4",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "头部体量明显过大，横向或纵向膨胀成巨型舱体、宽大动物头或接近上躯干尺度的块体。",
        "tier_1": "头部轮廓紧凑，横向宽度和整体体量均明显受限，呈小型装甲头。",
        "tier_2": "在满足Pass基础上，头部以极精炼的紧凑体量容纳清晰装甲与前脸细节，轮廓控制精准，在低机位透视下仍不显臃肿。"
      },
      "variants_used": "",
      "visibility_requirement": "需完整看到头部外轮廓；若被裁切、强光淹没或雨幕遮蔽到不能判断其体量，本条判为Fail。"
    },
    {
      "check": "头部相对于躯干的尺度明显更小，整体保持危险流浪者典型的小头大躯干比例。",
      "lens": "K4",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "头部与躯干尺度接近、比例关系不明显，或头部反而大于躯干主体；也包括透视处理使其呈普通人类式的大头比例。",
        "tier_1": "在画面透视下，头部宽度与体量均明确小于躯干，形成清楚的小头大躯干比例。",
        "tier_2": "在满足Pass基础上，头躯比例差异鲜明且稳定，肩部与胸部体量充分衬托紧凑头部，低机位夸张透视仍未破坏该尺度关系。"
      },
      "variants_used": "",
      "visibility_requirement": "头部与躯干必须同时完整可见并可直接比较；题面已要求正面全身无遮挡，若任一区域不可见或透视畸变到无法比较，本条判为Fail。"
    }
  ],
